/* Shared status semantics and keyboard-accessible record cards. */
(function(){
 const previousBadge=badge;
 badge=function(value){const label=String(value||'');let tone=/Tidak Qualified|Overdue|Over SLA|Ditolak|Lost|Tidak berhasil/i.test(label)?'danger':/Cancelled|Dibatalkan|Ditutup|Inactive|Nonaktif/i.test(label)?'neutral':/Won|Berhasil|Selesai|Disetujui|^Aktif$|Customer/i.test(label)?'success':/Menunggu|Belum|Baru|Hot|Warm/i.test(label)?'warning':'info';return previousBadge(value).replace('class="tag ','class="tag state-'+tone+' ')};
 function decorate(){const titles={'Lead detail':'Detail Lead','Nasabah detail':'Customer 360','Opportunity detail':'Detail Opportunity','Aktivitas detail':'Detail Task','Pengajuan detail':'Detail Pengajuan'};const title=document.querySelector('#title');if(title&&titles[view])title.textContent=titles[view];const app=document.querySelector('#app'),hero=app?.querySelector(':scope>.recordhero'),summary=app?.querySelector(':scope>.lead-workflow-summary');if(hero&&summary)app.insertBefore(hero,summary);for(const card of document.querySelectorAll('#app article.record')){const button=[...card.querySelectorAll('button[onclick]')].find(b=>/go\(['"](?:Lead detail|Opportunity detail|Aktivitas detail|Nasabah detail)['"]/.test(b.getAttribute('onclick')||''));if(!button)continue;card.tabIndex=0;card.setAttribute('role','link');card.setAttribute('aria-label',button.textContent+' · '+(card.querySelector('h3')?.textContent||''));card.onclick=e=>{if(!e.target.closest('button,a,input,select,textarea,label,summary'))button.click()};card.onkeydown=e=>{if(e.target===card&&['Enter',' '].includes(e.key)){e.preventDefault();button.click()}};}}
 const previous=renderContent;renderContent=function(){const result=previous.apply(this,arguments);decorate();return result};const previousRender=render;render=function(){const result=previousRender.apply(this,arguments);decorate();return result};decorate();
})();
